import React from 'react';
import { usePlayerStore } from '../../store/playerStore';
import { useSettingsStore } from '../../store/settingsStore';
import { useCoverUrl } from '../../utils/useCoverUrl';
import { AmllLyrics } from '../../amll/AmllLyrics';
import { FluidBackground } from '../../amll/FluidBackground';
import { SimpleLyricList } from '../player/SimpleLyricList';

/**
 * 面板右侧栏 (Apple Music 风格): 流体渐变背景 + 封面 + 弹簧滚动歌词。
 * 歌词引擎/流体背景都可以在设置里关闭，关闭后退回到简单列表/纯深色背景。
 */
export const Sidebar: React.FC = () => {
  const song = usePlayerStore((s) => s.currentSong);
  const lyrics = usePlayerStore((s) => s.lyrics);
  const settings = useSettingsStore((s) => s.settings);
  const cover = useCoverUrl(song?.pic_id, song?.source, 500);

  return (
    <div
      style={{
        width: 300,
        flexShrink: 0,
        position: 'relative',
        overflow: 'hidden',
        color: '#fff',
        borderLeft: '1px solid rgba(120,120,120,0.2)',
        display: 'flex',
        flexDirection: 'column',
        height: '100%',
        background: '#18181b',
      }}
    >
      {settings.fluidBackground && <FluidBackground cover={cover} />}

      <div style={{ position: 'relative', zIndex: 1, display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}>
        <div style={{ padding: '16px 16px 8px', display: 'flex', alignItems: 'center', gap: 12, flexShrink: 0 }}>
          <div
            style={{
              width: 72,
              height: 72,
              borderRadius: 8,
              overflow: 'hidden',
              flexShrink: 0,
              background: '#52525b',
              boxShadow: '0 6px 18px rgba(0,0,0,0.35)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            {cover ? (
              <img src={cover} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            ) : (
              <span style={{ color: 'rgba(255,255,255,0.6)', fontSize: 11 }}>专辑封面</span>
            )}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 700, fontSize: 14, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {song?.name || '未播放任何歌曲'}
            </div>
            <div style={{ fontSize: 12, opacity: 0.65, marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {song?.artist || ''}
            </div>
          </div>
        </div>

        <div style={{ flex: 1, minHeight: 0, position: 'relative' }}>
          {settings.lyricEngine === 'amll' ? (
            lyrics.length === 0 ? (
              <div style={{ textAlign: 'center', opacity: 0.5, marginTop: 40, fontSize: 13 }}>暂无歌词</div>
            ) : (
              <AmllLyrics fontSize={Math.max(16, Math.min(settings.lyricSize, 26))} enableBlur />
            )
          ) : (
            <SimpleLyricList />
          )}
        </div>
      </div>
    </div>
  );
};
