import React, { useEffect, useState } from 'react';
import { Icon } from '@capital/component';
import { showErrorToasts, showToasts } from '@capital/common';
import { LyricLine, MUSIC_SOURCES, MusicSource, Song } from '../../const';
import { getLyric, searchAlbumTracks, searchMusic } from '../../api/musicApi';
import { NavEntry, useNavStore } from '../../store/navStore';
import { usePlayerStore } from '../../store/playerStore';
import { useCoverUrl } from '../../utils/useCoverUrl';
import { mergeBilingualLrc, parseLrc } from '../../utils/lrc';
import {
  isFavorite,
  isFavoriteAlbum,
  isFollowingArtist,
  toggleFavorite,
  toggleFavoriteAlbum,
  toggleFollowArtist,
} from '../../utils/storage';
import { buildAlbumCardContent, buildArtistCardContent, buildSongCardContent } from '../../utils/share';
import { THEME } from '../../theme';
import { SongRow } from './SongRow';
import { AddToPlaylistMenu } from './AddToPlaylistMenu';

const ellipsis: React.CSSProperties = { overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' };

async function copyText(text: string, label: string) {
  try {
    await navigator.clipboard.writeText(text);
    showToasts(`${label}分享卡片已复制，可粘贴到任意聊天窗口发送`, 'success');
  } catch {
    showToasts('复制失败，请检查浏览器权限', 'error');
  }
}

const Header: React.FC<{ title: string }> = ({ title }) => {
  const pop = useNavStore((s) => s.pop);
  const depth = useNavStore((s) => s.stack.length);
  const clear = useNavStore((s) => s.clear);
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 12px', borderBottom: '1px solid rgba(120,120,120,0.15)', flexShrink: 0 }}>
      <Icon icon="mdi:arrow-left" width={18} style={{ cursor: 'pointer', flexShrink: 0 }} title="返回" onClick={pop} />
      <div style={{ flex: 1, minWidth: 0, fontWeight: 700, fontSize: 14, ...ellipsis }}>{title}</div>
      {depth > 1 && (
        <Icon icon="mdi:close" width={16} style={{ cursor: 'pointer', opacity: 0.6, flexShrink: 0 }} title="回到列表" onClick={clear} />
      )}
    </div>
  );
};

const ActionBtn: React.FC<{ icon: string; label: string; onClick: () => void; primary?: boolean; active?: boolean }> = ({
  icon,
  label,
  onClick,
  primary,
  active,
}) => (
  <div
    onClick={onClick}
    style={{
      display: 'inline-flex',
      alignItems: 'center',
      gap: 4,
      padding: '5px 12px',
      borderRadius: 16,
      fontSize: 12,
      cursor: 'pointer',
      background: primary ? THEME.primary : 'rgba(120,120,120,0.14)',
      color: primary ? '#fff' : active ? THEME.primary : 'inherit',
    }}
  >
    <Icon icon={icon} width={14} />
    {label}
  </div>
);

// ---------------- 歌曲详情 ----------------
const SongDetail: React.FC<{ song: Song }> = ({ song }) => {
  const push = useNavStore((s) => s.push);
  const playSong = usePlayerStore((s) => s.playSong);
  const cover = useCoverUrl(song.pic_id, song.source, 500);
  const [fav, setFav] = useState(() => isFavorite(song));
  const [lyrics, setLyrics] = useState<LyricLine[] | null>(null);
  const [lyricLoading, setLyricLoading] = useState(false);
  const sourceLabel = MUSIC_SOURCES.find((s) => s.value === song.source)?.label || song.source;

  useEffect(() => {
    setFav(isFavorite(song));
    let canceled = false;
    setLyrics(null);
    if (!song.lyric_id) return;
    setLyricLoading(true);
    getLyric(song.lyric_id, song.source)
      .then((res) => {
        if (canceled) return;
        setLyrics(mergeBilingualLrc(parseLrc(res.lyric || ''), parseLrc(res.tlyric || '')));
      })
      .catch(() => !canceled && setLyrics([]))
      .finally(() => !canceled && setLyricLoading(false));
    return () => {
      canceled = true;
    };
  }, [song.id, song.source, song.lyric_id]);

  const artists = song.artist.split(' / ').filter(Boolean);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Header title="歌曲详情" />
      <div style={{ flex: 1, overflowY: 'auto', padding: 16 }}>
        <div style={{ display: 'flex', gap: 16 }}>
          <div
            style={{
              width: 120,
              height: 120,
              borderRadius: 10,
              flexShrink: 0,
              overflow: 'hidden',
              background: '#a1a1aa',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            {cover ? (
              <img src={cover} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            ) : (
              <Icon icon="mdi:music-note" width={36} color="#fff" />
            )}
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 18, fontWeight: 700, overflowWrap: 'break-word', wordBreak: 'break-word', lineHeight: 1.35 }}>
              {song.name}
            </div>
            <div style={{ marginTop: 8, fontSize: 13, display: 'flex', flexWrap: 'wrap', gap: '2px 6px' }}>
              <span style={{ opacity: 0.55 }}>歌手</span>
              {artists.map((a, i) => (
                <span
                  key={i}
                  style={{ color: THEME.primary, cursor: 'pointer', overflowWrap: 'anywhere' }}
                  onClick={() => push({ type: 'artist', name: a, source: song.source, pic_id: song.pic_id })}
                >
                  {a}
                </span>
              ))}
            </div>
            {song.album && (
              <div style={{ marginTop: 4, fontSize: 13, display: 'flex', flexWrap: 'wrap', gap: '2px 6px' }}>
                <span style={{ opacity: 0.55 }}>专辑</span>
                <span
                  style={{ color: THEME.primary, cursor: 'pointer', overflowWrap: 'anywhere' }}
                  onClick={() => push({ type: 'album', name: song.album, artist: artists[0] || song.artist, source: song.source, pic_id: song.pic_id })}
                >
                  {song.album}
                </span>
              </div>
            )}
            <div style={{ marginTop: 4, fontSize: 12, opacity: 0.55 }}>
              音源 {sourceLabel} · ID {song.id}
            </div>
          </div>
        </div>

        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 14, alignItems: 'center' }}>
          <ActionBtn icon="mdi:play" label="播放" primary onClick={() => playSong(song, [song])} />
          <ActionBtn
            icon={fav ? 'mdi:heart' : 'mdi:heart-outline'}
            label={fav ? '已收藏' : '收藏'}
            active={fav}
            onClick={() => setFav(toggleFavorite(song))}
          />
          <ActionBtn icon="mdi:share-variant" label="复制分享卡片" onClick={() => copyText(buildSongCardContent(song), '歌曲')} />
          <AddToPlaylistMenu song={song} />
        </div>

        <div style={{ marginTop: 20, fontSize: 13, fontWeight: 700 }}>歌词</div>
        <div style={{ marginTop: 8, fontSize: 13, lineHeight: 1.9 }}>
          {lyricLoading && <div style={{ opacity: 0.5 }}>加载歌词中...</div>}
          {!lyricLoading && lyrics !== null && lyrics.filter((l) => l.text).length === 0 && (
            <div style={{ opacity: 0.5 }}>暂无歌词</div>
          )}
          {!lyricLoading &&
            lyrics?.map((l, i) =>
              l.text ? (
                <div key={i} style={{ overflowWrap: 'break-word', wordBreak: 'break-word' }}>
                  <div>{l.text}</div>
                  {l.tran && <div style={{ fontSize: 12, opacity: 0.55, marginTop: -4 }}>{l.tran}</div>}
                </div>
              ) : null
            )}
        </div>
      </div>
    </div>
  );
};

// ---------------- 专辑 / 歌手详情 (曲目列表) ----------------
const TrackListDetail: React.FC<{ entry: Extract<NavEntry, { type: 'album' | 'artist' }> }> = ({ entry }) => {
  const playSong = usePlayerStore((s) => s.playSong);
  const [songs, setSongs] = useState<Song[]>([]);
  const [loading, setLoading] = useState(true);
  const [, force] = useState(0);
  const isAlbum = entry.type === 'album';
  const albumArtist = entry.type === 'album' ? entry.artist : '';
  const favored = isAlbum
    ? isFavoriteAlbum(entry.name, albumArtist, entry.source)
    : isFollowingArtist(entry.name, entry.source);

  useEffect(() => {
    let canceled = false;
    setLoading(true);
    setSongs([]);
    const task =
      entry.type === 'album'
        ? searchAlbumTracks(entry.name, entry.source, 60).then((list) => {
            const exact = list.filter((s) => s.album === entry.name);
            return exact.length > 0 ? exact : list;
          })
        : searchMusic(entry.name, entry.source, 60);
    task
      .then((list) => !canceled && setSongs(list))
      .catch((e) => !canceled && showErrorToasts(e))
      .finally(() => !canceled && setLoading(false));
    return () => {
      canceled = true;
    };
  }, [entry.type, entry.name, entry.source]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Header title={isAlbum ? '专辑详情' : '歌手详情'} />
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 14px' }}>
        <div style={{ width: 56, height: 56, borderRadius: isAlbum ? 8 : '50%', flexShrink: 0, background: '#a1a1aa', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <Icon icon={isAlbum ? 'mdi:album' : 'mdi:account-music'} width={26} color="#fff" />
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 700, fontSize: 16, overflowWrap: 'break-word', wordBreak: 'break-word' }}>{entry.name}</div>
          <div style={{ fontSize: 12, opacity: 0.55, marginTop: 2, ...ellipsis }}>
            {isAlbum ? `专辑 · ${albumArtist}` : '歌手'}
            {!loading && ` · ${songs.length}首`}
          </div>
        </div>
      </div>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, padding: '0 14px 10px', alignItems: 'center' }}>
        <ActionBtn icon="mdi:play" label="播放全部" primary onClick={() => songs[0] && playSong(songs[0], songs)} />
        {isAlbum ? (
          <ActionBtn
            icon={favored ? 'mdi:heart' : 'mdi:heart-outline'}
            label={favored ? '已收藏' : '收藏专辑'}
            active={favored}
            onClick={() => {
              toggleFavoriteAlbum(entry.name, albumArtist, entry.source, entry.pic_id);
              force((n) => n + 1);
            }}
          />
        ) : (
          <ActionBtn
            icon={favored ? 'mdi:account-check' : 'mdi:account-plus-outline'}
            label={favored ? '已关注' : '关注歌手'}
            active={favored}
            onClick={() => {
              toggleFollowArtist(entry.name, entry.source, entry.pic_id);
              force((n) => n + 1);
            }}
          />
        )}
        <ActionBtn
          icon="mdi:share-variant"
          label="复制分享卡片"
          onClick={() => {
            if (!songs[0]) return;
            copyText(isAlbum ? buildAlbumCardContent(songs[0]) : buildArtistCardContent(songs[0]), isAlbum ? '专辑' : '歌手');
          }}
        />
      </div>
      <div style={{ flex: 1, overflowY: 'auto', padding: '0 12px 12px' }}>
        {loading && <div style={{ textAlign: 'center', opacity: 0.6, marginTop: 30 }}>加载中...</div>}
        {!loading && songs.length === 0 && <div style={{ textAlign: 'center', opacity: 0.4, marginTop: 30 }}>没有找到曲目</div>}
        {songs.map((song, i) => (
          <SongRow key={`${song.source}-${song.id}-${i}`} song={song} queue={songs} index={i} />
        ))}
      </div>
    </div>
  );
};

export const DetailView: React.FC<{ entry: NavEntry }> = ({ entry }) => {
  if (entry.type === 'song') return <SongDetail song={entry.song} />;
  return <TrackListDetail entry={entry} />;
};
