import React, { useEffect, useState } from 'react';
import { Icon } from '@capital/component';
import { showErrorToasts, showToasts } from '@capital/common';
import { FavoriteAlbum, FollowedArtist, Playlist, Song } from '../../const';
import {
  createPlaylist,
  deletePlaylist,
  getFavoriteAlbums,
  getFavorites,
  getFollowedArtists,
  getPlaylists,
  removeSongFromPlaylist,
  renamePlaylist,
  toggleFavoriteAlbum,
  toggleFollowArtist,
} from '../../utils/storage';
import { usePlayerStore } from '../../store/playerStore';
import { searchAlbumTracks, searchMusic } from '../../api/musicApi';
import { SongRow } from './SongRow';
import { buildPlaylistCardContent } from '../../utils/share';
import { THEME } from '../../theme';

const FAVORITES_ID = '__favorites__';
const QUEUE_ID = '__queue__';

export const Playlists: React.FC = () => {
  const [playlists, setPlaylists] = useState<Playlist[]>(getPlaylists());
  const [favorites, setFavorites] = useState<Song[]>(getFavorites());
  const [followedArtists, setFollowedArtists] = useState<FollowedArtist[]>(getFollowedArtists());
  const [favoriteAlbums, setFavoriteAlbums] = useState<FavoriteAlbum[]>(getFavoriteAlbums());
  const [openId, setOpenId] = useState<string | null>(QUEUE_ID);
  const [newName, setNewName] = useState('');
  const playSong = usePlayerStore((s) => s.playSong);
  const queue = usePlayerStore((s) => s.queue);

  useEffect(() => {
    const refresh = () => {
      setPlaylists(getPlaylists());
      setFavorites(getFavorites());
      setFollowedArtists(getFollowedArtists());
      setFavoriteAlbums(getFavoriteAlbums());
    };
    window.addEventListener('musicplayer:playlists-changed', refresh);
    window.addEventListener('musicplayer:favorites-changed', refresh);
    window.addEventListener('musicplayer:followed-artists-changed', refresh);
    window.addEventListener('musicplayer:favorite-albums-changed', refresh);
    return () => {
      window.removeEventListener('musicplayer:playlists-changed', refresh);
      window.removeEventListener('musicplayer:favorites-changed', refresh);
      window.removeEventListener('musicplayer:followed-artists-changed', refresh);
      window.removeEventListener('musicplayer:favorite-albums-changed', refresh);
    };
  }, []);

  const virtualQueuePlaylist: Playlist = {
    id: QUEUE_ID,
    name: '当前播放列表',
    createdAt: 0,
    songs: queue,
  };

  const virtualFavPlaylist: Playlist = {
    id: FAVORITES_ID,
    name: '我的收藏',
    createdAt: 0,
    songs: favorites,
  };

  const list = [virtualQueuePlaylist, virtualFavPlaylist, ...playlists];

  const copyShare = async (playlist: Playlist) => {
    try {
      await navigator.clipboard.writeText(buildPlaylistCardContent(playlist));
      showToasts('歌单分享卡片已复制，可粘贴到任意聊天窗口发送', 'success');
    } catch {
      showToasts('复制失败', 'error');
    }
  };

  const playArtist = async (artist: FollowedArtist) => {
    try {
      const songs = await searchMusic(artist.name, artist.source, 30);
      if (songs.length === 0) {
        showToasts('未找到该歌手的歌曲', 'warning');
        return;
      }
      playSong(songs[0], songs);
    } catch (e) {
      showErrorToasts(e);
    }
  };

  const playAlbum = async (album: FavoriteAlbum) => {
    try {
      const songs = await searchAlbumTracks(album.name, album.source, 60);
      const filtered = songs.filter((s) => s.album === album.name);
      const finalSongs = filtered.length > 0 ? filtered : songs;
      if (finalSongs.length === 0) {
        showToasts('未找到该专辑的曲目', 'warning');
        return;
      }
      playSong(finalSongs[0], finalSongs);
    } catch (e) {
      showErrorToasts(e);
    }
  };

  return (
    <div style={{ height: '100%', overflowY: 'auto', padding: 12 }}>
      <div style={{ display: 'flex', gap: 6, marginBottom: 10 }}>
        <input
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          placeholder="新建歌单名称"
          style={{ flex: 1, padding: '6px 10px', borderRadius: 6, border: '1px solid rgba(120,120,120,0.3)', background: 'transparent', color: 'inherit' }}
        />
        <div
          onClick={() => {
            if (!newName.trim()) return;
            createPlaylist(newName.trim());
            setNewName('');
          }}
          style={{ display: 'flex', alignItems: 'center', padding: '0 12px', borderRadius: 6, background: THEME.primary, color: '#fff', cursor: 'pointer' }}
        >
          <Icon icon="mdi:plus" width={16} />
        </div>
      </div>

      {list.map((pl) => (
        <div key={pl.id} style={{ marginBottom: 8, border: '1px solid rgba(120,120,120,0.2)', borderRadius: 10, overflow: 'hidden' }}>
          <div
            style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '10px 12px', cursor: 'pointer' }}
            onClick={() => setOpenId(openId === pl.id ? null : pl.id)}
          >
            <Icon icon={pl.id === QUEUE_ID ? 'mdi:playlist-play' : pl.id === FAVORITES_ID ? 'mdi:heart' : 'mdi:playlist-music'} width={18} />
            <div
              style={{
                flex: 1,
                minWidth: 0,
                fontWeight: 600,
                fontSize: 13,
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}
            >
              {pl.name}
            </div>
            <span style={{ fontSize: 12, opacity: 0.5 }}>{pl.songs.length}首</span>

            {pl.songs.length > 0 && (
              <Icon
                icon="mdi:play-circle-outline"
                width={18}
                onClick={(e: any) => {
                  e.stopPropagation();
                  playSong(pl.songs[0], pl.songs);
                }}
              />
            )}
            {pl.id !== FAVORITES_ID && pl.id !== QUEUE_ID && (
              <Icon
                icon="mdi:share-variant"
                width={16}
                onClick={(e: any) => {
                  e.stopPropagation();
                  copyShare(pl);
                }}
              />
            )}
            {pl.id !== FAVORITES_ID && pl.id !== QUEUE_ID && (
              <Icon
                icon="mdi:pencil"
                width={16}
                onClick={(e: any) => {
                  e.stopPropagation();
                  const name = window.prompt('重命名歌单', pl.name);
                  if (name) renamePlaylist(pl.id, name);
                }}
              />
            )}
            {pl.id !== FAVORITES_ID && pl.id !== QUEUE_ID && (
              <Icon
                icon="mdi:delete-outline"
                width={16}
                onClick={(e: any) => {
                  e.stopPropagation();
                  if (window.confirm(`删除歌单《${pl.name}》?`)) deletePlaylist(pl.id);
                }}
              />
            )}
          </div>

          {openId === pl.id && (
            <div style={{ padding: '0 10px 10px' }}>
              {pl.songs.length === 0 && <div style={{ opacity: 0.4, fontSize: 12, padding: 8 }}>暂无歌曲</div>}
              {pl.songs.map((song, i) => (
                <div key={`${song.source}-${song.id}`} style={{ display: 'flex', alignItems: 'center' }}>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <SongRow song={song} queue={pl.songs} index={i} />
                  </div>
                  {pl.id !== FAVORITES_ID && pl.id !== QUEUE_ID && (
                    <Icon
                      icon="mdi:close"
                      width={14}
                      style={{ cursor: 'pointer', opacity: 0.5, marginLeft: 4 }}
                      onClick={() => removeSongFromPlaylist(pl.id, song.id, song.source)}
                    />
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      ))}

      {(followedArtists.length > 0 || favoriteAlbums.length > 0) && (
        <>
          <div style={{ fontSize: 12, opacity: 0.5, margin: '14px 4px 6px', fontWeight: 700 }}>关注的歌手</div>
          {followedArtists.length === 0 && (
            <div style={{ opacity: 0.4, fontSize: 12, padding: '4px 6px' }}>暂无关注的歌手，可在「搜索」的歌手页里关注</div>
          )}
          {followedArtists.map((a) => (
            <div
              key={`${a.source}-${a.name}`}
              style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 6px', borderRadius: 8, cursor: 'pointer' }}
              onClick={() => playArtist(a)}
            >
              <div style={{ width: 34, height: 34, borderRadius: '50%', flexShrink: 0, background: '#a1a1aa', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Icon icon="mdi:account-music" width={16} color="#fff" />
              </div>
              <div style={{ flex: 1, minWidth: 0, fontSize: 13, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {a.name}
              </div>
              <Icon
                icon="mdi:close"
                width={14}
                style={{ opacity: 0.5, flexShrink: 0 }}
                onClick={(e: any) => {
                  e.stopPropagation();
                  toggleFollowArtist(a.name, a.source, a.pic_id);
                }}
              />
            </div>
          ))}

          <div style={{ fontSize: 12, opacity: 0.5, margin: '14px 4px 6px', fontWeight: 700 }}>收藏的专辑</div>
          {favoriteAlbums.length === 0 && (
            <div style={{ opacity: 0.4, fontSize: 12, padding: '4px 6px' }}>暂无收藏的专辑，可在「搜索」的专辑页里收藏</div>
          )}
          {favoriteAlbums.map((al) => (
            <div
              key={`${al.source}-${al.name}-${al.artist}`}
              style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 6px', borderRadius: 8, cursor: 'pointer' }}
              onClick={() => playAlbum(al)}
            >
              <div style={{ width: 34, height: 34, borderRadius: 6, flexShrink: 0, background: '#a1a1aa', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Icon icon="mdi:album" width={16} color="#fff" />
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{al.name}</div>
                <div style={{ fontSize: 11, opacity: 0.55, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{al.artist}</div>
              </div>
              <Icon
                icon="mdi:close"
                width={14}
                style={{ opacity: 0.5, flexShrink: 0 }}
                onClick={(e: any) => {
                  e.stopPropagation();
                  toggleFavoriteAlbum(al.name, al.artist, al.source, al.pic_id);
                }}
              />
            </div>
          ))}
        </>
      )}
    </div>
  );
};
