import { PLUGIN_ID } from '../const';
import { NavEntry, useNavStore } from '../store/navStore';

export const MUSIC_PANEL_PATH = `/main/custom/${PLUGIN_ID}/musicpanel`;

/**
 * 从面板之外(如聊天里的分享卡片)打开音乐面板并直接进入某个详情页。
 *
 * 做法: 先把目标写进全局导航栈，再用 history.pushState + 手动派发 popstate 触发
 * Tailchat 的前端路由跳转(不刷新页面)。popstate 派发是 SPA 路由库通用的"外部触发路由"手法，
 * 没有拿到宿主路由实例的官方 API，所以属于"尽力而为"；如果当前已经在音乐面板页面，
 * 只写导航栈就足够了，面板会直接响应。
 */
export function openMusicDetail(entry: NavEntry) {
  useNavStore.getState().reset(entry);
  if (!window.location.pathname.includes(`/custom/${PLUGIN_ID}/musicpanel`)) {
    window.history.pushState({}, '', MUSIC_PANEL_PATH);
    window.dispatchEvent(new PopStateEvent('popstate'));
  }
}
