import React, { useState } from 'react';
import { Icon } from '@capital/component';
import { showToasts } from '@capital/common';
import { Song } from '../../const';
import { usePlayerStore } from '../../store/playerStore';
import { useNavStore } from '../../store/navStore';
import { isFavorite, toggleFavorite } from '../../utils/storage';
import { buildSongCardContent } from '../../utils/share';
import { AddToPlaylistMenu } from './AddToPlaylistMenu';
import { THEME } from '../../theme';

async function copyShare(text: string, label: string) {
  try {
    await navigator.clipboard.writeText(text);
    showToasts(`${label}已复制，可粘贴到任意聊天窗口发送`, 'success');
  } catch {
    showToasts('复制失败，请检查浏览器权限', 'error');
  }
}

export const SongRow: React.FC<{
  song: Song;
  queue: Song[];
  index: number;
  onClickArtist?: (song: Song) => void;
  onClickAlbum?: (song: Song) => void;
}> = ({ song, queue, index, onClickArtist, onClickAlbum }) => {
  const playSong = usePlayerStore((s) => s.playSong);
  const push = useNavStore((s) => s.push);
  // 默认点歌手/专辑文字就进入对应详情页；调用方也可以传自定义处理函数覆盖
  const handleArtist =
    onClickArtist ??
    ((s: Song) => push({ type: 'artist', name: s.artist.split(' / ')[0] || s.artist, source: s.source, pic_id: s.pic_id }));
  const handleAlbum =
    onClickAlbum ??
    ((s: Song) =>
      s.album
        ? push({ type: 'album', name: s.album, artist: s.artist.split(' / ')[0] || s.artist, source: s.source, pic_id: s.pic_id })
        : undefined);
  const currentSong = usePlayerStore((s) => s.currentSong);
  const [fav, setFav] = useState(() => isFavorite(song));
  const active = currentSong?.id === song.id && currentSong?.source === song.source;

  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 8,
        padding: '8px 6px',
        borderRadius: 8,
        background: active ? 'rgba(24,144,255,0.12)' : 'transparent',
      }}
    >
      <span style={{ width: 20, fontSize: 12, opacity: 0.5, textAlign: 'center' }}>{index + 1}</span>
      <div style={{ flex: 1, minWidth: 0, cursor: 'pointer' }} onClick={() => playSong(song, queue)}>
        <div style={{ fontSize: 13, fontWeight: active ? 700 : 400, color: active ? THEME.primary : 'inherit', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {song.name}
        </div>
        <div style={{ fontSize: 11, opacity: 0.55, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          <span
            onClick={(e) => {
              e.stopPropagation();
              handleArtist(song);
            }}
            style={{ cursor: 'pointer', textDecoration: 'underline dotted' }}
          >
            {song.artist}
          </span>
          {song.album && (
            <>
              {' · '}
              <span
                onClick={(e) => {
                  e.stopPropagation();
                  handleAlbum(song);
                }}
                style={{ cursor: 'pointer', textDecoration: 'underline dotted' }}
              >
                {song.album}
              </span>
            </>
          )}
        </div>
      </div>

      <div
        style={{ cursor: 'pointer', display: 'flex' }}
        title="歌曲详情"
        onClick={() => push({ type: 'song', song })}
      >
        <Icon icon="mdi:information-outline" width={16} />
      </div>

      <div
        style={{ cursor: 'pointer', display: 'flex' }}
        title={fav ? '取消收藏' : '收藏'}
        onClick={() => setFav(toggleFavorite(song))}
      >
        <Icon icon={fav ? 'mdi:heart' : 'mdi:heart-outline'} width={16} color={fav ? '#f43f5e' : undefined} />
      </div>

      <AddToPlaylistMenu song={song} />

      <div
        style={{ cursor: 'pointer', display: 'flex' }}
        title="复制歌曲分享卡片"
        onClick={() => copyShare(buildSongCardContent(song), '歌曲')}
      >
        <Icon icon="mdi:share-variant" width={16} />
      </div>
    </div>
  );
};
