import React, { useState } from 'react';
import { Icon } from '@capital/component';
import { usePlayerStore } from '../../store/playerStore';
import { useSettingsStore } from '../../store/settingsStore';
import { useCoverUrl } from '../../utils/useCoverUrl';
import { THEME } from '../../theme';
import { AmllLyrics } from '../../amll/AmllLyrics';
import { FluidBackground } from '../../amll/FluidBackground';
import { SimpleLyricList } from './SimpleLyricList';
import { FavoriteButton, ModeButton, PlayControls, ProgressBar, VolumeControl } from './Controls';

/**
 * 完整播放器: 精简为更紧凑的尺寸，配色改为低饱和中性色 + Tailchat 主题色点缀，
 * 去掉了此前偏"AI 生成感"的大面积紫蓝渐变模糊背景。
 */
export const FullPlayer: React.FC<{ onCollapse: () => void; onClose: () => void }> = ({
  onCollapse,
  onClose,
}) => {
  const song = usePlayerStore((s) => s.currentSong);
  const queue = usePlayerStore((s) => s.queue);
  const lyrics = usePlayerStore((s) => s.lyrics);
  const playSong = usePlayerStore((s) => s.playSong);
  const settings = useSettingsStore((s) => s.settings);
  const cover = useCoverUrl(song?.pic_id, song?.source, 300);
  const [tab, setTab] = useState<'lyric' | 'queue'>('lyric');

  return (
    <div
      style={{
        position: 'fixed',
        right: 16,
        bottom: 16,
        zIndex: 999999,
        width: 300,
        height: 420,
        borderRadius: 14,
        overflow: 'hidden',
        color: '#e4e4e7',
        background: '#18181b',
        boxShadow: '0 10px 28px rgba(0,0,0,0.35)',
        display: 'flex',
        flexDirection: 'column',
      }}
    >
      {settings.fluidBackground && <FluidBackground cover={cover} />}

      {/* 顶部栏 */}
      <div style={{ display: 'flex', alignItems: 'center', padding: '8px 10px', flexShrink: 0, position: 'relative', zIndex: 1 }}>
        <div style={{ fontWeight: 600, fontSize: 12, opacity: 0.6 }}>正在播放</div>
        <div style={{ flex: 1 }} />
        <Icon
          icon="mdi:chevron-down"
          width={18}
          style={{ cursor: 'pointer', marginRight: 8, opacity: 0.6 }}
          onClick={onCollapse}
        />
        <Icon icon="mdi:close" width={16} style={{ cursor: 'pointer', opacity: 0.6 }} onClick={onClose} />
      </div>

      {tab === 'lyric' && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '0 14px 10px', flexShrink: 0, position: 'relative', zIndex: 1 }}>
          <div
            style={{
              width: 52,
              height: 52,
              borderRadius: 8,
              overflow: 'hidden',
              flexShrink: 0,
              background: '#3f3f46',
            }}
          >
            {cover && <img src={cover} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />}
          </div>
          <div style={{ minWidth: 0 }}>
            <div
              style={{
                fontSize: 14,
                fontWeight: 700,
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
              }}
            >
              {song?.name || '未播放'}
            </div>
            <div
              style={{
                fontSize: 12,
                opacity: 0.55,
                whiteSpace: 'nowrap',
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                marginTop: 2,
              }}
            >
              {song?.artist || ''}
            </div>
          </div>
        </div>
      )}

      {/* 歌词 / 播放列表 切换区域 */}
      <div
        style={{
          flex: 1,
          minHeight: 0,
          position: 'relative',
          zIndex: 1,
          overflowY: tab === 'queue' ? 'auto' : 'hidden',
          padding: tab === 'queue' ? '4px 16px' : 0,
          borderTop: '1px solid rgba(255,255,255,0.06)',
        }}
      >
        {tab === 'lyric' &&
          (settings.lyricEngine === 'amll' ? (
            lyrics.length > 0 ? (
              <AmllLyrics fontSize={Math.max(15, Math.min(settings.lyricSize - 2, 22))} enableBlur />
            ) : (
              <div style={{ textAlign: 'center', opacity: 0.5, marginTop: 30, fontSize: 13 }}>暂无歌词</div>
            )
          ) : (
            <SimpleLyricList scale={0.65} />
          ))}

        {tab === 'queue' &&
          queue.map((s, i) => (
            <div
              key={`${s.source}-${s.id}`}
              onClick={() => playSong(s, queue)}
              style={{
                display: 'flex',
                alignItems: 'center',
                padding: '7px 6px',
                borderRadius: 6,
                cursor: 'pointer',
                background:
                  s.id === song?.id && s.source === song?.source ? 'rgba(255,255,255,0.08)' : 'transparent',
              }}
            >
              <span style={{ width: 20, opacity: 0.4, fontSize: 11 }}>{i + 1}</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 12, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {s.name}
                </div>
                <div
                  style={{
                    fontSize: 11,
                    opacity: 0.5,
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                  }}
                >
                  {s.artist}
                </div>
              </div>
            </div>
          ))}
      </div>

      {/* 控制区 */}
      <div style={{ padding: '8px 14px 12px', flexShrink: 0, borderTop: '1px solid rgba(255,255,255,0.06)', position: 'relative', zIndex: 1 }}>
        <ProgressBar color={THEME.primary} />
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: 8 }}>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
            <ModeButton color="#e4e4e7" />
            <FavoriteButton color="#e4e4e7" />
          </div>
          <PlayControls size={18} color="#e4e4e7" />
          <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
            <VolumeControl color="#e4e4e7" />
            <Icon
              icon="mdi:playlist-music"
              width={16}
              color="#e4e4e7"
              style={{ cursor: 'pointer', opacity: tab === 'queue' ? 1 : 0.5 }}
              onClick={() => setTab(tab === 'queue' ? 'lyric' : 'queue')}
            />
          </div>
        </div>
      </div>
    </div>
  );
};
