import React, { useEffect, useRef, useState } from 'react';
import { BackgroundRender, MeshGradientRenderer } from './vendor/amll-core';
import { usePlayerStore } from '../store/playerStore';

interface Props {
  /** 封面图片地址 */
  cover: string;
  style?: React.CSSProperties;
}

/**
 * Apple Music 风格的流体渐变背景 (WebGL, 基于封面取色)。
 *
 * 注意两个现实限制，所以必须有降级方案:
 * 1. 需要 WebGL2 (旧设备/某些虚拟机里不可用)；
 * 2. WebGL 纹理上传要求图片"可跨域读取"——封面来自网易云/QQ音乐等第三方图片 CDN，
 *    如果对方没有返回 CORS 头，图片会加载失败。
 * 任一环节失败都会退回到「封面图高斯模糊 + 压暗」的静态背景，不会影响歌词和播放。
 */
export const FluidBackground: React.FC<Props> = ({ cover, style }) => {
  const hostRef = useRef<HTMLDivElement>(null);
  const bgRef = useRef<BackgroundRender<MeshGradientRenderer> | null>(null);
  const [failed, setFailed] = useState(false);
  const playing = usePlayerStore((s) => s.playing);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    try {
      const bg = BackgroundRender.new(MeshGradientRenderer);
      const canvas = bg.getElement();
      canvas.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;display:block;';
      host.appendChild(canvas);
      bg.setFPS(30);
      bg.setRenderScale(0.5);
      bgRef.current = bg;
    } catch (e) {
      console.warn('[com.custom.musicplayer] fluid background unavailable, fallback to blurred cover', e);
      setFailed(true);
      return;
    }
    return () => {
      try {
        bgRef.current?.dispose();
      } catch {
        /* ignore */
      }
      bgRef.current = null;
    };
  }, []);

  useEffect(() => {
    const bg = bgRef.current;
    if (!bg || !cover) return;
    let canceled = false;
    bg.setAlbum(cover)
      .then(() => {
        if (!canceled) setFailed(false);
      })
      .catch((e) => {
        if (canceled) return;
        console.warn('[com.custom.musicplayer] fluid background cover load failed (likely CORS)', e);
        setFailed(true);
      });
    return () => {
      canceled = true;
    };
  }, [cover]);

  useEffect(() => {
    const bg = bgRef.current;
    if (!bg) return;
    if (playing) bg.resume();
    else bg.pause();
  }, [playing]);

  return (
    <div style={{ position: 'absolute', inset: 0, overflow: 'hidden', background: '#18181b', ...style }}>
      <div ref={hostRef} style={{ position: 'absolute', inset: 0, opacity: failed ? 0 : 1 }} />
      {failed && cover && (
        <div
          style={{
            position: 'absolute',
            inset: -30,
            backgroundImage: `url(${cover})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            filter: 'blur(40px) brightness(0.55) saturate(1.2)',
          }}
        />
      )}
      <div style={{ position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.18)' }} />
    </div>
  );
};
