import React, { useState } from 'react';
import { Icon } from '@capital/component';
import { Search } from './Search';
import { Playlists } from './Playlists';
import { SettingsPanel } from './SettingsPanel';
import { Sidebar } from './Sidebar';
import { DetailView } from './DetailView';
import { useNavStore } from '../../store/navStore';
import { TransportBar } from './TransportBar';
import { Translate } from '../../translate';
import { THEME } from '../../theme';

type TabKey = 'search' | 'playlists' | 'settings';

const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: 'search', label: Translate.search, icon: 'mdi:magnify' },
  { key: 'playlists', label: Translate.playlists, icon: 'mdi:playlist-music' },
  { key: 'settings', label: Translate.settings, icon: 'mdi:cog' },
];

/**
 * 整体布局参考设计图: 顶部 Tab 切换栏 / 左侧内容列表 + 右侧封面歌词栏 / 底部常驻播放条
 */
export const MusicPanel: React.FC = React.memo(() => {
  const [tab, setTab] = useState<TabKey>('search');
  const navTop = useNavStore((s) => s.stack[s.stack.length - 1]);
  const clearNav = useNavStore((s) => s.clear);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', width: '100%' }}>
      {/* 顶部 Tab 栏 */}
      <div style={{ display: 'flex', borderBottom: '1px solid rgba(120,120,120,0.2)' }}>
        {TABS.map((t) => (
          <div
            key={t.key}
            onClick={() => {
              clearNav();
              setTab(t.key);
            }}
            style={{
              flex: 1,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: 6,
              padding: '12px 0',
              cursor: 'pointer',
              fontSize: 13,
              fontWeight: tab === t.key ? 700 : 400,
              color: tab === t.key ? THEME.primary : 'inherit',
              borderBottom: tab === t.key ? `2px solid ${THEME.primary}` : '2px solid transparent',
            }}
          >
            <Icon icon={t.icon} width={16} />
            {t.label}
          </div>
        ))}
      </div>

      {/* 中间内容区: 左侧列表 + 右侧封面/歌词栏 (设置页不需要侧栏，占满全宽) */}
      <div style={{ flex: 1, display: 'flex', overflow: 'hidden', minHeight: 0 }}>
        <div style={{ flex: 1, minWidth: 0, overflow: 'hidden' }}>
          {/* 各 Tab 与详情页互斥显示，但 Tab 内容始终保持挂载(仅 display 切换)，
              这样从详情页返回/切换 Tab 后，搜索关键字和结果不会丢失 */}
          <div style={{ height: '100%', display: navTop ? 'none' : 'block' }}>
            <div style={{ height: '100%', display: tab === 'search' ? 'block' : 'none' }}>
              <Search />
            </div>
            <div style={{ height: '100%', display: tab === 'playlists' ? 'block' : 'none' }}>
              <Playlists />
            </div>
            <div style={{ height: '100%', display: tab === 'settings' ? 'block' : 'none' }}>
              <SettingsPanel />
            </div>
          </div>
          {navTop && <DetailView entry={navTop} />}
        </div>
        {(tab !== 'settings' || navTop) && <Sidebar />}
      </div>

      {/* 底部常驻播放条 */}
      <TransportBar />
    </div>
  );
});
MusicPanel.displayName = 'MusicPanel';
