import { createStore } from '../utils/createStore';
import { MusicSource, Song } from '../const';

/** 面板内的"详情页导航栈"条目: 歌曲 / 专辑 / 歌手 */
export type NavEntry =
  | { type: 'song'; song: Song }
  | { type: 'album'; name: string; artist: string; source: MusicSource; pic_id?: string }
  | { type: 'artist'; name: string; source: MusicSource; pic_id?: string };

interface NavState {
  stack: NavEntry[];
  push: (entry: NavEntry) => void;
  pop: () => void;
  clear: () => void;
  /** 直接替换整个栈(例如从聊天卡片进入时，只保留目标详情页) */
  reset: (entry: NavEntry) => void;
}

/**
 * 模块级(全局)导航状态，而不是放在 React 组件里:
 * 聊天消息里的音乐卡片在音乐面板之外渲染，点击后需要"先设置要看的详情，再打开面板"，
 * 面板挂载时直接读取这里的栈即可，不依赖任何 React 上下文。
 */
export const useNavStore = createStore<NavState>((set, get) => ({
  stack: [],
  push: (entry) => set({ stack: [...get().stack, entry] }),
  pop: () => set({ stack: get().stack.slice(0, -1) }),
  clear: () => set({ stack: [] }),
  reset: (entry) => set({ stack: [entry] }),
}));
