import React, { useMemo, useState } from 'react';
import { Icon } from '@capital/component';
import { showErrorToasts } from '@capital/common';
import { MUSIC_SOURCES, MusicSource, Song } from '../../const';
import { searchAlbumTracks, searchMusic } from '../../api/musicApi';
import { useSettingsStore } from '../../store/settingsStore';
import { usePlayerStore } from '../../store/playerStore';
import { useNavStore } from '../../store/navStore';
import { SongRow } from './SongRow';
import { Translate } from '../../translate';
import { THEME } from '../../theme';

type Mode = 'song' | 'album' | 'artist';

interface AlbumGroup {
  name: string;
  artist: string;
  source: MusicSource;
  pic_id?: string;
  count: number;
}

interface ArtistGroup {
  name: string;
  source: MusicSource;
  pic_id?: string;
  count: number;
}

const MODES: { key: Mode; label: string }[] = [
  { key: 'song', label: '歌曲' },
  { key: 'album', label: '专辑' },
  { key: 'artist', label: '歌手' },
];

const rowPlaceholder: React.CSSProperties = {
  width: 40,
  height: 40,
  borderRadius: 8,
  flexShrink: 0,
  background: '#a1a1aa',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
};

const ellipsis: React.CSSProperties = { overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' };

const RetryHint: React.FC<{ keyword: string; empty: string; onRetry: () => void }> = ({ keyword, empty, onRetry }) => (
  <div style={{ textAlign: 'center', opacity: 0.4, marginTop: 30 }}>
    {keyword.trim() ? (
      <>
        没有搜索到结果，音源接口偶尔会抽风，
        <span style={{ color: THEME.primary, cursor: 'pointer', textDecoration: 'underline' }} onClick={onRetry}>
          点此重试
        </span>
      </>
    ) : (
      empty
    )}
  </div>
);

export const Search: React.FC = () => {
  const defaultSource = useSettingsStore((s) => s.settings.defaultSource);
  const [mode, setMode] = useState<Mode>('song');
  const [source, setSource] = useState<MusicSource>(defaultSource);
  const [keyword, setKeyword] = useState('');
  const [results, setResults] = useState<Song[]>([]);
  const [loading, setLoading] = useState(false);
  const playSong = usePlayerStore((s) => s.playSong);
  const push = useNavStore((s) => s.push);

  const doSearch = async () => {
    if (!keyword.trim()) return;
    setLoading(true);
    try {
      if (mode === 'album') {
        setResults(await searchAlbumTracks(keyword.trim(), source, 60));
      } else if (mode === 'artist') {
        setResults(await searchMusic(keyword.trim(), source, 60));
      } else {
        setResults(await searchMusic(keyword.trim(), source, 30));
      }
    } catch (e) {
      showErrorToasts(e);
    } finally {
      setLoading(false);
    }
  };

  const albumGroups: AlbumGroup[] = useMemo(() => {
    if (mode !== 'album') return [];
    const map = new Map<string, AlbumGroup>();
    for (const s of results) {
      if (!s.album) continue;
      const key = `${s.source}__${s.album}__${s.artist}`;
      const existing = map.get(key);
      if (existing) existing.count += 1;
      else map.set(key, { name: s.album, artist: s.artist, source: s.source, pic_id: s.pic_id, count: 1 });
    }
    return Array.from(map.values());
  }, [results, mode]);

  const artistGroups: ArtistGroup[] = useMemo(() => {
    if (mode !== 'artist') return [];
    const map = new Map<string, ArtistGroup>();
    for (const s of results) {
      const key = `${s.source}__${s.artist}`;
      const existing = map.get(key);
      if (existing) existing.count += 1;
      else map.set(key, { name: s.artist, source: s.source, pic_id: s.pic_id, count: 1 });
    }
    return Array.from(map.values());
  }, [results, mode]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <div style={{ display: 'flex', gap: 6, padding: '10px 12px 0' }}>
        {MODES.map((m) => (
          <div
            key={m.key}
            onClick={() => {
              setMode(m.key);
              setResults([]);
            }}
            style={{
              padding: '4px 12px',
              borderRadius: 14,
              fontSize: 12,
              cursor: 'pointer',
              background: mode === m.key ? THEME.primary : 'rgba(120,120,120,0.12)',
              color: mode === m.key ? '#fff' : 'inherit',
            }}
          >
            {m.label}
          </div>
        ))}
      </div>

      <div style={{ display: 'flex', gap: 8, padding: '10px 12px' }}>
        <select
          value={source}
          onChange={(e) => setSource(e.target.value as MusicSource)}
          style={{ padding: '6px 8px', borderRadius: 6, border: '1px solid rgba(120,120,120,0.3)', background: 'transparent', color: 'inherit' }}
        >
          {MUSIC_SOURCES.map((s) => (
            <option key={s.value} value={s.value}>
              {s.label}
            </option>
          ))}
        </select>
        <input
          value={keyword}
          onChange={(e) => setKeyword(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && doSearch()}
          placeholder={mode === 'album' ? '搜索专辑名' : mode === 'artist' ? '搜索歌手名' : Translate.searchPlaceholder}
          style={{ flex: 1, minWidth: 0, padding: '6px 10px', borderRadius: 6, border: '1px solid rgba(120,120,120,0.3)', background: 'transparent', color: 'inherit' }}
        />
        <div
          onClick={doSearch}
          style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '0 12px', borderRadius: 6, background: THEME.primary, color: '#fff', cursor: 'pointer' }}
        >
          <Icon icon="mdi:magnify" width={18} />
        </div>
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: '0 12px 12px' }}>
        {loading && <div style={{ textAlign: 'center', opacity: 0.6, marginTop: 30 }}>搜索中...</div>}

        {!loading && mode === 'song' && results.length === 0 && (
          <RetryHint keyword={keyword} empty="输入关键字搜索歌曲" onRetry={doSearch} />
        )}
        {!loading && mode === 'song' && results.length > 0 && (
          <div style={{ display: 'flex', justifyContent: 'flex-end', marginBottom: 4 }}>
            <div
              style={{ fontSize: 12, cursor: 'pointer', opacity: 0.7, display: 'flex', alignItems: 'center', gap: 4 }}
              onClick={() => results[0] && playSong(results[0], results)}
            >
              <Icon icon="mdi:play" width={14} /> 播放全部
            </div>
          </div>
        )}
        {!loading &&
          mode === 'song' &&
          results.map((song, i) => <SongRow key={`${song.source}-${song.id}-${i}`} song={song} queue={results} index={i} />)}

        {!loading && mode === 'album' && albumGroups.length === 0 && (
          <RetryHint keyword={keyword} empty="输入专辑名搜索" onRetry={doSearch} />
        )}
        {!loading &&
          mode === 'album' &&
          albumGroups.map((g, i) => (
            <div
              key={i}
              onClick={() => push({ type: 'album', name: g.name, artist: g.artist, source: g.source, pic_id: g.pic_id })}
              style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 6px', borderRadius: 8, cursor: 'pointer' }}
            >
              <div style={rowPlaceholder}>
                <Icon icon="mdi:album" color="#fff" width={18} />
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, fontWeight: 600, ...ellipsis }}>{g.name}</div>
                <div style={{ fontSize: 11, opacity: 0.55, ...ellipsis }}>
                  {g.artist} · {g.count}首
                </div>
              </div>
              <Icon icon="mdi:chevron-right" width={18} style={{ opacity: 0.4, flexShrink: 0 }} />
            </div>
          ))}

        {!loading && mode === 'artist' && artistGroups.length === 0 && (
          <RetryHint keyword={keyword} empty="输入歌手名搜索" onRetry={doSearch} />
        )}
        {!loading &&
          mode === 'artist' &&
          artistGroups.map((g, i) => (
            <div
              key={i}
              onClick={() => push({ type: 'artist', name: g.name, source: g.source, pic_id: g.pic_id })}
              style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '8px 6px', borderRadius: 8, cursor: 'pointer' }}
            >
              <div style={{ ...rowPlaceholder, borderRadius: '50%' }}>
                <Icon icon="mdi:account-music" color="#fff" width={18} />
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 13, fontWeight: 600, ...ellipsis }}>{g.name}</div>
                <div style={{ fontSize: 11, opacity: 0.55, ...ellipsis }}>{g.count}首相关歌曲</div>
              </div>
              <Icon icon="mdi:chevron-right" width={18} style={{ opacity: 0.4, flexShrink: 0 }} />
            </div>
          ))}
      </div>
    </div>
  );
};
