import { useEffect, useState } from 'react';
import { getPicUrl } from '../api/musicApi';
import { MusicSource } from '../const';

/**
 * 统一的封面获取 hook，修复"换歌后封面未刷新/显示了上一首歌封面"的问题。
 *
 * 根因：多个组件里各自写了一份 `getPicUrl(...).then(setCover)`，切歌很快时，
 * 旧请求有可能比新请求更晚返回（网络时序不保证顺序），旧请求的 setCover 会把
 * 已经更新好的新封面重新覆盖回旧的。这里用一个"本次 effect 是否已失效"的标记，
 * 请求返回时先检查是否仍然对应当前歌曲，不是的话直接丢弃结果。
 */
export function useCoverUrl(
  picId: string | undefined,
  source: MusicSource | undefined,
  size: 300 | 500 = 300
): string {
  const [cover, setCover] = useState('');

  useEffect(() => {
    let cancelled = false;

    if (!picId || !source) {
      setCover('');
      return;
    }

    // 切歌时先清空，避免短暂展示上一首歌的封面
    setCover('');

    getPicUrl(picId, source, size)
      .then((url) => {
        if (!cancelled) setCover(url);
      })
      .catch(() => undefined);

    return () => {
      cancelled = true;
    };
  }, [picId, source, size]);

  return cover;
}
