import { API_BASE, MusicSource, Song } from '../const';

async function req<T = any>(params: Record<string, string | number>): Promise<T> {
  const qs = Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== null && v !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join('&');
  const res = await fetch(`${API_BASE}?${qs}`);
  if (!res.ok) {
    throw new Error(`music api error: ${res.status}`);
  }
  return res.json();
}

function delay(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * GD音乐台的接口偶尔会在参数完全正确、关键字明明有结果的情况下返回空数组 `[]`
 * （HTTP 200，大概率是上游接口自身的限流/反爬虫策略导致的偶发性失败，而不是真的
 * "没有搜索结果"）。这里对"结果为空数组"的情况做几次短暂延迟后的自动重试，减少
 * 偶发性失败对使用体验的影响；重试全部失败后再如实返回空数组，交给上层 UI 提示用户
 * 可以手动重试。
 */
async function withRetryOnEmpty<T>(
  fn: () => Promise<T[]>,
  retries = 2,
  delays = [400, 900]
): Promise<T[]> {
  let result = await fn();
  let attempt = 0;
  while (result.length === 0 && attempt < retries) {
    await delay(delays[attempt] ?? 900);
    attempt += 1;
    try {
      result = await fn();
    } catch {
      // 重试请求本身失败(网络问题等)，跳出重试循环，把空结果原样返回给上层处理
      break;
    }
  }
  return result;
}

export interface RawSearchItem {
  id: string;
  name: string;
  artist: string[];
  album: string;
  pic_id: string;
  url_id: string;
  lyric_id: string;
  source: MusicSource;
}

async function rawSearch(
  keyword: string,
  source: MusicSource,
  count: number,
  pages: number
): Promise<Song[]> {
  const list = await req<RawSearchItem[]>({
    types: 'search',
    source,
    name: keyword,
    count,
    pages,
  });

  if (!Array.isArray(list)) {
    return [];
  }

  return list.map((item) => ({
    id: String(item.id),
    source: item.source || source,
    name: item.name,
    artist: Array.isArray(item.artist) ? item.artist.join(' / ') : String(item.artist),
    album: item.album,
    pic_id: item.pic_id,
    lyric_id: item.lyric_id,
  }));
}

/**
 * 搜索歌曲 (关键字可以是曲目名/歌手名/专辑名)
 */
export async function searchMusic(
  keyword: string,
  source: MusicSource = 'netease',
  count = 30,
  pages = 1
): Promise<Song[]> {
  return withRetryOnEmpty(() => rawSearch(keyword, source, count, pages));
}

/**
 * 搜索专辑内曲目列表 (专辑用 `${source}_album`)
 */
export async function searchAlbumTracks(
  albumName: string,
  source: MusicSource = 'netease',
  count = 50
): Promise<Song[]> {
  return searchMusic(albumName, `${source}_album` as MusicSource, count);
}

/**
 * 获取播放直链
 */
export async function getSongUrl(
  id: string,
  source: MusicSource = 'netease',
  br: number | string = 320
): Promise<{ url: string; br: number; size: number }> {
  return req({ types: 'url', source, id, br });
}

/**
 * 获取专辑图
 */
export async function getPicUrl(
  picId: string,
  source: MusicSource = 'netease',
  size: 300 | 500 = 300
): Promise<string> {
  const data = await req<{ url: string }>({
    types: 'pic',
    source,
    id: picId,
    size,
  });
  return data.url;
}

/**
 * 获取歌词 (原语言 + 可能的翻译)
 */
export async function getLyric(
  lyricId: string,
  source: MusicSource = 'netease'
): Promise<{ lyric: string; tlyric?: string }> {
  return req({ types: 'lyric', source, id: lyricId });
}
