import React, { useEffect, useMemo, useState } from 'react';
import { GroupPanelContainer, Icon } from '@capital/component';
import { postRequest, showErrorToasts, showToasts, useGroupPanelContext } from '@capital/common';
import { MUSIC_SOURCES, MusicSource, Song } from '../../const';
import { searchAlbumTracks, searchMusic } from '../../api/musicApi';
import { usePlayerStore } from '../../store/playerStore';
import { openMusicDetail } from '../../utils/navigate';
import { createPlaylist, addSongToPlaylist, getFavoriteAlbums, getFavorites, getFollowedArtists, getPlaylists } from '../../utils/storage';
import { THEME } from '../../theme';

/** 群面板里固定的内容条目 (会保存到群面板的 meta.items，群内所有成员看到的是同一份) */
export type BoardItem =
  | { uid: string; type: 'song'; song: Song }
  | { uid: string; type: 'album'; name: string; artist: string; source: MusicSource; pic_id?: string }
  | { uid: string; type: 'artist'; name: string; source: MusicSource; pic_id?: string }
  | { uid: string; type: 'playlist'; name: string; songs: Song[] };

const MAX_PLAYLIST_SONGS = 50;
const ellipsis: React.CSSProperties = { overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' };
const uid = () => `b_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const compactSong = (s: Song): Song => ({ id: s.id, source: s.source, name: s.name, artist: s.artist, album: s.album, pic_id: s.pic_id, lyric_id: s.lyric_id });

function sameItem(a: BoardItem, b: BoardItem) {
  if (a.type !== b.type) return false;
  if (a.type === 'song' && b.type === 'song') return a.song.id === b.song.id && a.song.source === b.song.source;
  if (a.type === 'album' && b.type === 'album') return a.name === b.name && a.artist === b.artist && a.source === b.source;
  if (a.type === 'artist' && b.type === 'artist') return a.name === b.name && a.source === b.source;
  if (a.type === 'playlist' && b.type === 'playlist') return a.name === b.name;
  return false;
}

const Chip: React.FC<{ active?: boolean; onClick: () => void }> = ({ active, onClick, children }) => (
  <div
    onClick={onClick}
    style={{ display: 'inline-block', padding: '3px 12px', borderRadius: 14, fontSize: 12, cursor: 'pointer', background: active ? THEME.primary : 'rgba(120,120,120,0.14)', color: active ? '#fff' : 'inherit' }}
  >
    {children}
  </div>
);

const Row: React.FC<{ icon: string; round?: boolean; title: string; sub?: string; onClick?: () => void; right?: React.ReactNode }> = ({
  icon,
  round,
  title,
  sub,
  onClick,
  right,
}) => (
  <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '7px 6px', borderRadius: 8 }}>
    <div
      onClick={onClick}
      style={{ width: 36, height: 36, borderRadius: round ? '50%' : 8, flexShrink: 0, background: '#a1a1aa', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: onClick ? 'pointer' : 'default' }}
    >
      <Icon icon={icon} width={16} color="#fff" />
    </div>
    <div style={{ flex: 1, minWidth: 0, cursor: onClick ? 'pointer' : 'default' }} onClick={onClick}>
      <div style={{ fontSize: 13, fontWeight: 600, ...ellipsis }}>{title}</div>
      {sub && <div style={{ fontSize: 11, opacity: 0.55, ...ellipsis }}>{sub}</div>}
    </div>
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>{right}</div>
  </div>
);

// ---------------- 添加内容面板 ----------------
type AddTab = 'search' | 'mine' | 'current';

const AddPanel: React.FC<{ onAdd: (item: BoardItem) => void }> = ({ onAdd }) => {
  const [tab, setTab] = useState<AddTab>('search');
  const [mode, setMode] = useState<'song' | 'album' | 'artist'>('song');
  const [source, setSource] = useState<MusicSource>('netease');
  const [keyword, setKeyword] = useState('');
  const [results, setResults] = useState<Song[]>([]);
  const [loading, setLoading] = useState(false);
  const currentSong = usePlayerStore((s) => s.currentSong);

  const doSearch = async () => {
    if (!keyword.trim()) return;
    setLoading(true);
    try {
      setResults(mode === 'album' ? await searchAlbumTracks(keyword.trim(), source, 60) : await searchMusic(keyword.trim(), source, 40));
    } catch (e) {
      showErrorToasts(e);
    } finally {
      setLoading(false);
    }
  };

  const albums = useMemo(() => {
    const m = new Map<string, Song>();
    results.forEach((s) => s.album && !m.has(`${s.album}__${s.artist}`) && m.set(`${s.album}__${s.artist}`, s));
    return Array.from(m.values());
  }, [results]);
  const artists = useMemo(() => {
    const m = new Map<string, Song>();
    results.forEach((s) => !m.has(s.artist) && m.set(s.artist, s));
    return Array.from(m.values());
  }, [results]);

  const Plus: React.FC<{ onClick: () => void }> = ({ onClick }) => (
    <Icon icon="mdi:plus-circle-outline" width={20} style={{ cursor: 'pointer', color: THEME.primary }} title="固定到群面板" onClick={onClick} />
  );
  const addSong = (s: Song) => onAdd({ uid: uid(), type: 'song', song: compactSong(s) });

  return (
    <div style={{ border: '1px solid rgba(120,120,120,0.25)', borderRadius: 10, padding: 10, margin: '8px 0' }}>
      <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
        <Chip active={tab === 'search'} onClick={() => setTab('search')}>搜索</Chip>
        <Chip active={tab === 'mine'} onClick={() => setTab('mine')}>我的歌单/收藏</Chip>
        <Chip active={tab === 'current'} onClick={() => setTab('current')}>正在播放</Chip>
      </div>

      {tab === 'search' && (
        <>
          <div style={{ display: 'flex', gap: 6, marginBottom: 6 }}>
            {(['song', 'album', 'artist'] as const).map((m) => (
              <Chip key={m} active={mode === m} onClick={() => { setMode(m); setResults([]); }}>
                {m === 'song' ? '歌曲' : m === 'album' ? '专辑' : '歌手'}
              </Chip>
            ))}
          </div>
          <div style={{ display: 'flex', gap: 6, marginBottom: 6 }}>
            <select value={source} onChange={(e) => setSource(e.target.value as MusicSource)} style={{ padding: '4px 6px', borderRadius: 6, border: '1px solid rgba(120,120,120,0.3)', background: 'transparent', color: 'inherit' }}>
              {MUSIC_SOURCES.map((s) => (<option key={s.value} value={s.value}>{s.label}</option>))}
            </select>
            <input
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && doSearch()}
              placeholder="搜索后点 + 固定到群面板"
              style={{ flex: 1, minWidth: 0, padding: '4px 8px', borderRadius: 6, border: '1px solid rgba(120,120,120,0.3)', background: 'transparent', color: 'inherit' }}
            />
            <div onClick={doSearch} style={{ padding: '0 10px', display: 'flex', alignItems: 'center', background: THEME.primary, color: '#fff', borderRadius: 6, cursor: 'pointer' }}>
              <Icon icon="mdi:magnify" width={16} />
            </div>
          </div>
          <div style={{ maxHeight: 220, overflowY: 'auto' }}>
            {loading && <div style={{ textAlign: 'center', opacity: 0.6 }}>搜索中...</div>}
            {!loading && mode === 'song' && results.map((s, i) => (<Row key={i} icon="mdi:music-note" title={s.name} sub={`${s.artist} · ${s.album}`} right={<Plus onClick={() => addSong(s)} />} />))}
            {!loading && mode === 'album' && albums.map((s, i) => (<Row key={i} icon="mdi:album" title={s.album} sub={s.artist} right={<Plus onClick={() => onAdd({ uid: uid(), type: 'album', name: s.album, artist: s.artist, source: s.source, pic_id: s.pic_id })} />} />))}
            {!loading && mode === 'artist' && artists.map((s, i) => (<Row key={i} icon="mdi:account-music" round title={s.artist} right={<Plus onClick={() => onAdd({ uid: uid(), type: 'artist', name: s.artist, source: s.source, pic_id: s.pic_id })} />} />))}
          </div>
        </>
      )}

      {tab === 'mine' && (
        <div style={{ maxHeight: 260, overflowY: 'auto' }}>
          <div style={{ fontSize: 12, opacity: 0.55, margin: '2px 4px' }}>我的歌单</div>
          {getPlaylists().length === 0 && <div style={{ fontSize: 12, opacity: 0.4, padding: 6 }}>暂无歌单</div>}
          {getPlaylists().map((p) => (
            <Row key={p.id} icon="mdi:playlist-music" title={p.name} sub={`${p.songs.length}首`} right={<Plus onClick={() => onAdd({ uid: uid(), type: 'playlist', name: p.name, songs: p.songs.slice(0, MAX_PLAYLIST_SONGS).map(compactSong) })} />} />
          ))}
          <div style={{ fontSize: 12, opacity: 0.55, margin: '8px 4px 2px' }}>收藏的歌曲</div>
          {getFavorites().slice(0, 50).map((s, i) => (<Row key={i} icon="mdi:heart" title={s.name} sub={s.artist} right={<Plus onClick={() => addSong(s)} />} />))}
          <div style={{ fontSize: 12, opacity: 0.55, margin: '8px 4px 2px' }}>收藏的专辑</div>
          {getFavoriteAlbums().map((a, i) => (<Row key={i} icon="mdi:album" title={a.name} sub={a.artist} right={<Plus onClick={() => onAdd({ uid: uid(), type: 'album', name: a.name, artist: a.artist, source: a.source, pic_id: a.pic_id })} />} />))}
          <div style={{ fontSize: 12, opacity: 0.55, margin: '8px 4px 2px' }}>关注的歌手</div>
          {getFollowedArtists().map((a, i) => (<Row key={i} icon="mdi:account-music" round title={a.name} right={<Plus onClick={() => onAdd({ uid: uid(), type: 'artist', name: a.name, source: a.source, pic_id: a.pic_id })} />} />))}
        </div>
      )}

      {tab === 'current' && (
        <div>
          {currentSong ? (
            <Row icon="mdi:music-note" title={currentSong.name} sub={currentSong.artist} right={<Plus onClick={() => addSong(currentSong)} />} />
          ) : (
            <div style={{ fontSize: 12, opacity: 0.5, padding: 8 }}>当前没有正在播放的歌曲</div>
          )}
        </div>
      )}
    </div>
  );
};

// ---------------- 面板主体 ----------------
const Section: React.FC<{ title: string }> = ({ title }) => (
  <div style={{ fontSize: 12, opacity: 0.55, fontWeight: 700, margin: '14px 4px 4px' }}>{title}</div>
);

export const GroupBoard: React.FC<{ panelInfo: any }> = ({ panelInfo }) => {
  const { groupId, panelId } = useGroupPanelContext();
  const playSong = usePlayerStore((s) => s.playSong);
  const metaItems: BoardItem[] = Array.isArray(panelInfo?.meta?.items) ? panelInfo.meta.items : [];
  const [items, setItems] = useState<BoardItem[]>(metaItems);
  const [manage, setManage] = useState(false);
  const [adding, setAdding] = useState(false);
  const [openPlaylist, setOpenPlaylist] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  // 服务端 meta 变化(其他管理员编辑后推送)时同步到本地
  useEffect(() => {
    setItems(Array.isArray(panelInfo?.meta?.items) ? panelInfo.meta.items : []);
  }, [JSON.stringify(panelInfo?.meta?.items ?? [])]);

  const save = async (next: BoardItem[]) => {
    const prev = items;
    setItems(next);
    setSaving(true);
    try {
      await postRequest('/group/modifyGroupPanel', {
        groupId,
        panelId,
        name: panelInfo.name,
        type: panelInfo.type,
        parentId: panelInfo.parentId,
        provider: panelInfo.provider,
        pluginPanelName: panelInfo.pluginPanelName,
        meta: { ...(panelInfo.meta || {}), items: next },
      });
    } catch (e) {
      setItems(prev);
      showToasts('保存失败：只有拥有「管理面板」权限的成员才能编辑群音乐面板', 'error');
    } finally {
      setSaving(false);
    }
  };

  const addItem = (item: BoardItem) => {
    if (items.some((i) => sameItem(i, item))) {
      showToasts('已经固定过了', 'info');
      return;
    }
    save([...items, item]);
    showToasts('已固定到群面板', 'success');
  };
  const removeItem = (id: string) => save(items.filter((i) => i.uid !== id));

  const songs = items.filter((i): i is Extract<BoardItem, { type: 'song' }> => i.type === 'song');
  const albums = items.filter((i): i is Extract<BoardItem, { type: 'album' }> => i.type === 'album');
  const artists = items.filter((i): i is Extract<BoardItem, { type: 'artist' }> => i.type === 'artist');
  const playlists = items.filter((i): i is Extract<BoardItem, { type: 'playlist' }> => i.type === 'playlist');
  const boardSongs = songs.map((s) => s.song);

  const Remove: React.FC<{ id: string }> = ({ id }) =>
    manage ? <Icon icon="mdi:close" width={15} style={{ cursor: 'pointer', opacity: 0.6 }} title="从群面板移除" onClick={() => removeItem(id)} /> : null;

  return (
    <GroupPanelContainer groupId={groupId} panelId={panelId}>
      <div style={{ height: '100%', overflowY: 'auto', padding: '14px 18px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <Icon icon="mdi:music-box-multiple" width={22} />
          <div style={{ flex: 1, minWidth: 0, fontSize: 16, fontWeight: 700, ...ellipsis }}>群音乐板</div>
          {saving && <span style={{ fontSize: 12, opacity: 0.5 }}>保存中...</span>}
          <Chip active={manage} onClick={() => { setManage((m) => !m); setAdding(false); }}>{manage ? '完成' : '管理'}</Chip>
        </div>

        {manage && (
          <div style={{ marginTop: 8 }}>
            <Chip active={adding} onClick={() => setAdding((a) => !a)}>{adding ? '收起' : '+ 添加内容'}</Chip>
            {adding && <AddPanel onAdd={addItem} />}
          </div>
        )}

        {items.length === 0 && (
          <div style={{ textAlign: 'center', opacity: 0.45, marginTop: 50, fontSize: 13, lineHeight: 1.9 }}>
            这里还没有内容
            <br />
            有「管理面板」权限的成员点右上角「管理」→「添加内容」，可以固定歌单、专辑、歌手或单曲
          </div>
        )}

        {playlists.length > 0 && <Section title="歌单" />}
        {playlists.map((p) => (
          <div key={p.uid}>
            <Row
              icon="mdi:playlist-music"
              title={p.name}
              sub={`${p.songs.length}首`}
              onClick={() => setOpenPlaylist(openPlaylist === p.uid ? null : p.uid)}
              right={
                <>
                  <Icon icon="mdi:play-circle-outline" width={20} style={{ cursor: 'pointer' }} title="播放歌单" onClick={() => p.songs[0] && playSong(p.songs[0], p.songs)} />
                  <Icon
                    icon="mdi:download"
                    width={17}
                    style={{ cursor: 'pointer' }}
                    title="导入到我的歌单"
                    onClick={() => {
                      const pl = createPlaylist(p.name);
                      p.songs.forEach((s) => addSongToPlaylist(pl.id, s));
                      showToasts(`已导入歌单《${p.name}》`, 'success');
                    }}
                  />
                  <Remove id={p.uid} />
                </>
              }
            />
            {openPlaylist === p.uid && (
              <div style={{ paddingLeft: 24 }}>
                {p.songs.map((s, i) => (
                  <Row key={i} icon="mdi:music-note" title={s.name} sub={s.artist} onClick={() => playSong(s, p.songs)} right={<Icon icon="mdi:information-outline" width={16} style={{ cursor: 'pointer' }} title="歌曲详情" onClick={() => openMusicDetail({ type: 'song', song: s })} />} />
                ))}
              </div>
            )}
          </div>
        ))}

        {albums.length > 0 && <Section title="专辑" />}
        {albums.map((a) => (
          <Row key={a.uid} icon="mdi:album" title={a.name} sub={a.artist} onClick={() => openMusicDetail({ type: 'album', name: a.name, artist: a.artist, source: a.source, pic_id: a.pic_id })} right={<Remove id={a.uid} />} />
        ))}

        {artists.length > 0 && <Section title="歌手" />}
        {artists.map((a) => (
          <Row key={a.uid} icon="mdi:account-music" round title={a.name} onClick={() => openMusicDetail({ type: 'artist', name: a.name, source: a.source, pic_id: a.pic_id })} right={<Remove id={a.uid} />} />
        ))}

        {songs.length > 0 && (
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <div style={{ flex: 1 }}><Section title="单曲" /></div>
            <span style={{ fontSize: 12, color: THEME.primary, cursor: 'pointer' }} onClick={() => boardSongs[0] && playSong(boardSongs[0], boardSongs)}>播放全部</span>
          </div>
        )}
        {songs.map((s) => (
          <Row
            key={s.uid}
            icon="mdi:music-note"
            title={s.song.name}
            sub={`${s.song.artist} · ${s.song.album}`}
            onClick={() => playSong(s.song, boardSongs)}
            right={
              <>
                <Icon icon="mdi:information-outline" width={16} style={{ cursor: 'pointer' }} title="歌曲详情" onClick={() => openMusicDetail({ type: 'song', song: s.song })} />
                <Remove id={s.uid} />
              </>
            }
          />
        ))}
      </div>
    </GroupPanelContainer>
  );
};
