import { createStore as create } from '../utils/createStore';
import { LyricLine, PlayMode, Song, STORAGE_KEYS } from '../const';
import { getSongUrl, getLyric } from '../api/musicApi';
import { findCurrentLyricIndex, mergeBilingualLrc, parseLrc } from '../utils/lrc';
import { getSettingsSnapshot } from './settingsStore';
import { pushHistory } from '../utils/storage';

interface PlayerState {
  queue: Song[];
  currentIndex: number;
  currentSong: Song | null;
  playing: boolean;
  loading: boolean;
  currentTime: number;
  duration: number;
  volume: number;
  muted: boolean;
  mode: PlayMode;
  lyrics: LyricLine[];
  currentLyricIndex: number;
  visible: boolean; // 是否展示播放器 UI (关闭按钮控制)
  restored: boolean; // 是否是从上次会话恢复而来 (未经用户主动播放)

  playSong: (song: Song, queue?: Song[]) => Promise<void>;
  togglePlay: () => void;
  next: () => void;
  prev: () => void;
  seek: (time: number) => void;
  setVolume: (v: number) => void;
  toggleMute: () => void;
  cycleMode: () => void;
  setVisible: (visible: boolean) => void;
  enqueue: (songs: Song[]) => void;
}

interface LastSession {
  song: Song;
  queue: Song[];
  currentIndex: number;
  time: number;
  mode: PlayMode;
  volume: number;
}

let audio: HTMLAudioElement | null = null;

function getAudio(): HTMLAudioElement {
  if (!audio) {
    audio = new Audio();
    audio.preload = 'auto';
  }
  return audio;
}

function loadLastSession(): LastSession | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.lastSession);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed?.song?.id) return null;
    return parsed;
  } catch {
    return null;
  }
}

function saveLastSession(session: LastSession) {
  try {
    localStorage.setItem(STORAGE_KEYS.lastSession, JSON.stringify(session));
  } catch {
    // storage 写入失败(容量满等)不影响播放本身
  }
}

const lastSessionOnLoad = loadLastSession();

export const usePlayerStore = create<PlayerState>((set, get) => {
  const a = getAudio();
  let lastPersistAt = 0;

  const persistSession = (force = false) => {
    const { currentSong, queue, currentIndex, mode, volume } = get();
    if (!currentSong) return;
    const now = Date.now();
    if (!force && now - lastPersistAt < 4000) return; // 至少间隔 4s，避免频繁写 localStorage
    lastPersistAt = now;
    saveLastSession({
      song: currentSong,
      queue,
      currentIndex,
      time: a.currentTime || 0,
      mode,
      volume,
    });
  };

  a.addEventListener('timeupdate', () => {
    const { lyrics } = get();
    const currentTime = a.currentTime;
    set({
      currentTime,
      currentLyricIndex: findCurrentLyricIndex(lyrics, currentTime),
    });
    persistSession();
  });
  a.addEventListener('loadedmetadata', () => set({ duration: a.duration || 0 }));
  a.addEventListener('play', () => set({ playing: true, restored: false }));
  a.addEventListener('pause', () => {
    set({ playing: false });
    persistSession(true);
  });
  a.addEventListener('waiting', () => set({ loading: true }));
  a.addEventListener('canplay', () => set({ loading: false }));
  a.addEventListener('ended', () => {
    const { mode } = get();
    if (mode === 'loop') {
      a.currentTime = 0;
      a.play();
    } else {
      get().next();
    }
  });

  if (typeof window !== 'undefined') {
    window.addEventListener('beforeunload', () => persistSession(true));
  }

  /**
   * 内部通用加载函数: playSong 与"恢复上次会话"共用。
   * autoplay=false 时只加载音源/歌词/跳转到指定进度，不触发播放
   * (可规避浏览器对无用户交互 autoplay 的限制，也符合"恢复但不打扰"的预期)。
   */
  async function loadSong(
    song: Song,
    queue: Song[] | undefined,
    opts: { autoplay: boolean; resumeAt?: number }
  ) {
    const nextQueue = queue ?? get().queue;
    const idx = nextQueue.findIndex((s) => s.id === song.id && s.source === song.source);

    set({
      currentSong: song,
      queue: nextQueue,
      currentIndex: idx >= 0 ? idx : get().currentIndex,
      loading: true,
      lyrics: [],
      currentLyricIndex: -1,
      currentTime: opts.resumeAt || 0,
      visible: true,
    });

    if (opts.autoplay) {
      pushHistory(song);
    }

    try {
      const settings = getSettingsSnapshot();
      const [urlInfo, lyricInfo] = await Promise.all([
        getSongUrl(song.id, song.source, settings.quality),
        song.lyric_id
          ? getLyric(song.lyric_id, song.source).catch(() => null)
          : Promise.resolve(null),
      ]);

      if (get().currentSong?.id !== song.id || get().currentSong?.source !== song.source) return; // 用户已切歌

      if (lyricInfo) {
        const origin = parseLrc(lyricInfo.lyric || '');
        const tran = parseLrc(lyricInfo.tlyric || '');
        set({ lyrics: mergeBilingualLrc(origin, tran) });
      }

      if (urlInfo?.url) {
        a.src = urlInfo.url;
        a.volume = get().muted ? 0 : get().volume;

        if (opts.resumeAt) {
          const onceReady = () => {
            a.currentTime = opts.resumeAt as number;
            a.removeEventListener('loadedmetadata', onceReady);
          };
          a.addEventListener('loadedmetadata', onceReady);
        }

        if (opts.autoplay) {
          await a.play().catch(() => undefined);
        }
      }
    } finally {
      set({ loading: false });
    }
  }

  // 尝试恢复上次播放会话: 只加载信息/定位进度，不自动播放 (需要用户点一下播放键继续)
  if (lastSessionOnLoad) {
    setTimeout(() => {
      loadSong(lastSessionOnLoad.song, lastSessionOnLoad.queue, {
        autoplay: false,
        resumeAt: lastSessionOnLoad.time,
      }).catch(() => undefined);
      set({ mode: lastSessionOnLoad.mode, restored: true });
    }, 0);
  }

  return {
    queue: lastSessionOnLoad?.queue ?? [],
    currentIndex: lastSessionOnLoad?.currentIndex ?? -1,
    currentSong: null,
    playing: false,
    loading: false,
    currentTime: 0,
    duration: 0,
    volume: lastSessionOnLoad?.volume ?? 0.8,
    muted: false,
    mode: lastSessionOnLoad?.mode ?? 'order',
    lyrics: [],
    currentLyricIndex: -1,
    visible: true,
    restored: false,

    enqueue: (songs) => {
      set({ queue: [...get().queue, ...songs] });
    },

    playSong: async (song, queue) => {
      await loadSong(song, queue, { autoplay: true });
      persistSession(true);
    },

    togglePlay: () => {
      if (!a.src) return;
      if (a.paused) {
        a.play();
      } else {
        a.pause();
      }
    },

    next: () => {
      const { queue, currentIndex, mode } = get();
      if (queue.length === 0) return;
      let nextIdx: number;
      if (mode === 'random') {
        nextIdx = Math.floor(Math.random() * queue.length);
      } else {
        nextIdx = (currentIndex + 1) % queue.length;
      }
      get().playSong(queue[nextIdx], queue);
    },

    prev: () => {
      const { queue, currentIndex, mode } = get();
      if (queue.length === 0) return;
      let prevIdx: number;
      if (mode === 'random') {
        prevIdx = Math.floor(Math.random() * queue.length);
      } else {
        prevIdx = (currentIndex - 1 + queue.length) % queue.length;
      }
      get().playSong(queue[prevIdx], queue);
    },

    seek: (time) => {
      a.currentTime = time;
      set({ currentTime: time });
      persistSession(true);
    },

    setVolume: (v) => {
      a.volume = v;
      a.muted = false;
      set({ volume: v, muted: false });
    },

    toggleMute: () => {
      const muted = !get().muted;
      a.muted = muted;
      set({ muted });
    },

    cycleMode: () => {
      const order: PlayMode[] = ['order', 'random', 'loop'];
      const idx = order.indexOf(get().mode);
      set({ mode: order[(idx + 1) % order.length] });
    },

    setVisible: (visible) => set({ visible }),
  };
});

export function getAudioElement() {
  return getAudio();
}
