import React, { useEffect, useMemo, useRef } from 'react';
import { DomLyricPlayer, LayoutAlignAnchor } from './vendor/amll-core';
import { AMLL_CSS } from './style';
import { toAmllLines } from './convertLyrics';
import { usePlayerStore, getAudioElement } from '../store/playerStore';

let styleInjected = false;
/** 只注入一次 AMLL 的样式表 (插件是单文件，没法 import css) */
export function ensureAmllStyle() {
  if (styleInjected || typeof document === 'undefined') return;
  styleInjected = true;
  const el = document.createElement('style');
  el.id = 'tailchat-music-amll-style';
  el.textContent = AMLL_CSS;
  document.head.appendChild(el);
}

interface Props {
  /** 歌词文字大小(px)，映射到 AMLL 的 --amll-lp-font-size */
  fontSize?: number;
  /** 文字颜色，默认白色（AMLL 默认走 mix-blend-mode: plus-lighter，所以需要深色背景） */
  color?: string;
  enableBlur?: boolean;
  /** 当前行对齐位置 0~1，默认 0.4 偏上，更接近 Apple Music */
  alignPosition?: number;
  style?: React.CSSProperties;
}

/**
 * Apple Music 风格歌词 (基于 @applemusic-like-lyrics/core 的 DomLyricPlayer)。
 *
 * 没有用它的 React 绑定 (@applemusic-like-lyrics/react): 绑定要靠 React state 把 currentTime 每帧
 * 推进去，会让整个包装组件每秒重渲染几十次；这里直接用 rAF 读取 <audio>.currentTime 推给核心
 * 播放器，React 完全不参与逐帧更新。
 */
export const AmllLyrics: React.FC<Props> = ({
  fontSize = 22,
  color = '#fff',
  enableBlur = true,
  alignPosition = 0.4,
  style,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const playerRef = useRef<DomLyricPlayer | null>(null);
  const lyrics = usePlayerStore((s) => s.lyrics);
  const duration = usePlayerStore((s) => s.duration);
  const playing = usePlayerStore((s) => s.playing);
  const amllLines = useMemo(() => toAmllLines(lyrics, duration), [lyrics, duration]);
  const amllLinesRef = useRef(amllLines);
  amllLinesRef.current = amllLines;

  // 创建/销毁核心播放器 + 逐帧驱动
  useEffect(() => {
    ensureAmllStyle();
    const container = containerRef.current;
    if (!container) return;

    let player: DomLyricPlayer;
    try {
      player = new DomLyricPlayer();
    } catch (e) {
      console.warn('[com.custom.musicplayer] AMLL lyric player init failed', e);
      return;
    }
    playerRef.current = player;
    container.appendChild(player.getElement());
    player.setAlignAnchor(LayoutAlignAnchor.Center);
    player.setAlignPosition(alignPosition);
    player.setEnableBlur(enableBlur);
    player.setLyricLines(amllLinesRef.current, Math.floor(getAudioElement().currentTime * 1000));
    player.update();

    const audio = getAudioElement();
    let lastMs = Math.floor(audio.currentTime * 1000);
    let lastFrame = -1;
    let raf = 0;
    let canceled = false;

    const onFrame = (t: number) => {
      if (canceled) return;
      if (lastFrame === -1) lastFrame = t;
      const ms = Math.floor(audio.currentTime * 1000);
      // 进度突变(用户拖动进度条/点击歌词跳转)时告诉播放器这是一次 seek，让它强制重新排版
      const isSeek = Math.abs(ms - lastMs) > 1200;
      player.setCurrentTime(ms, isSeek);
      lastMs = ms;
      player.update(t - lastFrame);
      lastFrame = t;
      raf = requestAnimationFrame(onFrame);
    };
    raf = requestAnimationFrame(onFrame);

    const onLineClick = (e: any) => {
      const startTime = amllLinesRef.current[e?.lineIndex]?.startTime;
      if (typeof startTime === 'number') {
        usePlayerStore.getState().seek(startTime / 1000);
      }
    };
    player.addEventListener('line-click', onLineClick as any);

    return () => {
      canceled = true;
      cancelAnimationFrame(raf);
      try {
        player.removeEventListener('line-click', onLineClick as any);
        player.dispose();
      } catch {
        /* ignore */
      }
      playerRef.current = null;
    };
    // 只在挂载/卸载时创建，其余参数用下面的 effect 增量更新
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const player = playerRef.current;
    if (!player) return;
    player.setLyricLines(amllLines, Math.floor(getAudioElement().currentTime * 1000));
    player.update();
  }, [amllLines]);

  useEffect(() => {
    const player = playerRef.current;
    if (!player) return;
    if (playing) player.resume();
    else player.pause();
  }, [playing]);

  useEffect(() => {
    playerRef.current?.setEnableBlur(enableBlur);
  }, [enableBlur]);

  useEffect(() => {
    playerRef.current?.setAlignPosition(alignPosition);
  }, [alignPosition]);

  return (
    <div
      ref={containerRef}
      style={
        {
          width: '100%',
          height: '100%',
          position: 'relative',
          '--amll-lp-font-size': `${fontSize}px`,
          '--amll-lp-color': color,
          ...style,
        } as React.CSSProperties
      }
    />
  );
};
