import type { LyricLine as AmllLyricLine } from './vendor/amll-core';
import { LyricLine } from '../const';

/**
 * 把本插件的 LRC 行级歌词 (秒) 转成 AMLL 需要的歌词结构 (毫秒)。
 * LRC 只有行级时间戳，没有逐字时间，所以每行只放一个"单词"，起止时间为本行到下一行开始；
 * 这样 AMLL 仍然会有行级的弹簧滚动/模糊/缩放效果，只是没有逐字高亮 (需要 YRC/QRC/TTML 才有)。
 * 空文本行(间奏占位)直接丢弃——AMLL 会根据行与行之间的时间间隙自己生成间奏点动画。
 */
export function toAmllLines(lines: LyricLine[], durationSec?: number): AmllLyricLine[] {
  const filtered = lines.filter((l) => l.text && l.text.trim());
  return filtered.map((line, i) => {
    const startTime = Math.round(line.time * 1000);
    const next = filtered[i + 1];
    const fallbackEnd = durationSec && durationSec > line.time ? durationSec * 1000 : startTime + 5000;
    const endTime = Math.max(startTime + 500, Math.round(next ? next.time * 1000 : fallbackEnd));
    return {
      words: [{ word: line.text.trim(), startTime, endTime }],
      translatedLyric: line.tran || '',
      romanLyric: '',
      startTime,
      endTime,
      isBG: false,
      isDuet: false,
    };
  });
}
